from bio import bio
bio("umar", [
 ("هُوَ عُمَرُ بْنُ الْخَطَّابِ، أَمِيرُ الْمُؤْمِنِينَ، وَلَقَبُهُ الْفَارُوقُ.", "Er ist ʿUmar ibn al-Khattab, der Befehlshaber der Gläubigen, mit dem Beinamen al-Faruq.", 1216),
 ("أَسْلَمَ فِي السَّنَةِ السَّادِسَةِ مِنَ النُّبُوَّةِ، وَعُمُرُهُ سَبْعٌ وَعِشْرُونَ سَنَةً.", "Er nahm im sechsten Jahr des Prophetentums den Islam an, mit 27 Jahren.", 1216),
 ("دَعَا النَّبِيُّ ﷺ أَنْ يُعِزَّ اللَّهُ الْإِسْلَامَ بِعُمَرَ.", "Der Prophet ﷺ bat Allah, den Islam durch ʿUmar zu stärken.", 1217),
 ("قَالَ ابْنُ مَسْعُودٍ: مَا زِلْنَا أَعِزَّةً مُنْذُ أَسْلَمَ عُمَرُ.", "Ibn Masʿud sagte: Seit ʿUmar Muslim wurde, waren wir stark.", 1217),
 ("أَخْبَرَ النَّبِيُّ ﷺ أَنَّ الشَّيْطَانَ إِذَا لَقِيَ عُمَرَ فِي طَرِيقٍ سَلَكَ طَرِيقًا آخَرَ.", "Der Prophet ﷺ berichtete: Wenn der Satan ʿUmar auf einem Weg begegnet, nimmt er einen anderen Weg.", 1219),
 ("وَقَالَ النَّبِيُّ ﷺ: إِنْ يَكُنْ فِي أُمَّتِي مُحَدَّثٌ فَهُوَ عُمَرُ.", "Der Prophet ﷺ sagte: Wenn es in meiner Umma einen Inspirierten (muhaddath) gibt, dann ist es ʿUmar.", 1220),
 ("وَقَالَ عُمَرُ: وَافَقْتُ رَبِّي فِي ثَلَاثٍ، مِنْهَا مَقَامُ إِبْرَاهِيمَ وَالْحِجَابُ.", "ʿUmar sagte: In drei Dingen stimmte ich mit meinem Herrn überein, darunter der Maqam Ibrahim und der Hidschab.", 1221),
 ("رَأَى النَّبِيُّ ﷺ فِي الْمَنَامِ أَنَّهُ أَعْطَى عُمَرَ بَقِيَّةَ لَبَنِهِ، وَفَسَّرَ ذَلِكَ بِالْعِلْمِ.", "Der Prophet ﷺ sah im Traum, dass er ʿUmar den Rest seiner Milch gab, und deutete es als Wissen.", 1222),
 ("وَرَأَى النَّبِيُّ ﷺ فِي الْجَنَّةِ قَصْرًا لِعُمَرَ.", "Und der Prophet ﷺ sah im Paradies einen Palast für ʿUmar.", 1222),
 ("وَاسْتُشْهِدَ فِي آخِرِ ذِي الْحِجَّةِ سَنَةَ ثَلَاثٍ وَعِشْرِينَ.", "Er starb als Märtyrer Ende Dhul-Hiddscha im Jahr 23.", 1216),
], [
 ("hadith", "قد كان في الأمم محدثون فإن يكن في أمتي أحد فعمر بن الخطاب", "In den früheren Gemeinschaften gab es Inspirierte; wenn es in meiner Umma einen gibt, dann ist es ʿUmar ibn al-Khattab.", 1220, "رواه مسلم (laut adh-Dhahabi)"),
 ("athar", "ما زلنا أعزة منذ أسلم عمر.", "Seit ʿUmar Muslim wurde, waren wir stark. (Ibn Masʿud)", 1217),
 ("athar", "وافقت ربي في ثلاث: في مقام إبراهيم، وفي الحجاب", "Ich stimmte mit meinem Herrn in drei Dingen überein: beim Maqam Ibrahim und beim Hidschab … (ʿUmar)", 1221),
])
bio("uthman", [
 ("هُوَ عُثْمَانُ بْنُ عَفَّانَ، أَمِيرُ الْمُؤْمِنِينَ، مِنْ بَنِي أُمَيَّةَ.", "Er ist ʿUthman ibn ʿAffan, der Befehlshaber der Gläubigen, aus dem Stamm Banu Umayya.", 1291),
 ("كَانَ مِنَ السَّابِقِينَ الْأَوَّلِينَ إِلَى الْإِسْلَامِ.", "Er gehörte zu den Ersten, die den Islam annahmen.", 1291),
 ("تَزَوَّجَ رُقَيَّةَ بِنْتَ النَّبِيِّ ﷺ، وَهَاجَرَ بِهَا إِلَى الْحَبَشَةِ.", "Er heiratete Ruqayya, die Tochter des Propheten ﷺ, und wanderte mit ihr nach Abessinien aus.", 1291),
 ("وَتَخَلَّفَ عَنْ بَدْرٍ لِيُمَرِّضَهَا، فَأَعْطَاهُ النَّبِيُّ ﷺ سَهْمَهُ مِنْ بَدْرٍ.", "Er blieb von Badr fern, um sie zu pflegen, und der Prophet ﷺ gab ihm seinen Anteil von Badr.", 1292),
 ("ثُمَّ زَوَّجَهُ النَّبِيُّ ﷺ ابْنَتَهُ أُمَّ كُلْثُومٍ، فَسُمِّيَ ذَا النُّورَيْنِ.", "Dann verheiratete ihn der Prophet ﷺ mit seiner Tochter Umm Kulthum; deshalb wurde er „der mit den zwei Lichtern“ genannt.", 1293),
 ("وَجَاءَ بِأَلْفِ دِينَارٍ حِينَ جُهِّزَ جَيْشُ الْعُسْرَةِ.", "Er brachte tausend Dinar, als das Heer der Bedrängnis ausgerüstet wurde.", 1294),
 ("وَاشْتَرَى بِئْرَ رُومَةَ وَجَعَلَهَا لِلْمُسْلِمِينَ.", "Und er kaufte den Brunnen Ruma und stiftete ihn den Muslimen.", 1295),
 ("وَكَانَتِ الْمَلَائِكَةُ تَسْتَحْيِي مِنْهُ، كَمَا قَالَ النَّبِيُّ ﷺ.", "Selbst die Engel hatten Scheu vor ihm, wie der Prophet ﷺ sagte.", 1295),
 ("وَبَشَّرَهُ النَّبِيُّ ﷺ بِالْجَنَّةِ عَلَى بَلْوَى تُصِيبُهُ.", "Der Prophet ﷺ verkündete ihm das Paradies, nach einer Prüfung, die ihn treffen würde.", 1296),
], [
 ("hadith", "ألا أستحيي من رجل تستحيي منه الملائكة", "Soll ich keine Scheu vor einem Mann haben, vor dem selbst die Engel Scheu haben?", 1295, "رواه مسلم (laut adh-Dhahabi)"),
 ("athar", 'إنما سمي عثمان "ذا النورين"؛ لأنا لا نعلم أحدا أغلق بابه على ابنتي نبي غيره.', "ʿUthman wurde „der mit den zwei Lichtern“ genannt, weil wir niemanden außer ihm kennen, der mit zwei Töchtern eines Propheten verheiratet war. (al-Hasan)", 1293),
 ("athar", "كنا نقول على عهد رسول الله ﷺ: أبو بكر ثم عمر، ثم عثمان.", "Zur Zeit des Gesandten Allahs ﷺ sagten wir: Abu Bakr, dann ʿUmar, dann ʿUthman. (Ibn ʿUmar)", 1297, "رواه جماعة عن ابن عمر (laut adh-Dhahabi)"),
])
bio("ali", [
 ("هُوَ عَلِيُّ بْنُ أَبِي طَالِبٍ، أَمِيرُ الْمُؤْمِنِينَ، أَبُو الْحَسَنِ.", "Er ist ʿAli ibn Abi Talib, der Befehlshaber der Gläubigen, Abu l-Hasan.", 1365),
 ("وَهُوَ ابْنُ عَمِّ النَّبِيِّ ﷺ وَزَوْجُ ابْنَتِهِ فَاطِمَةَ.", "Er war der Cousin des Propheten ﷺ und der Ehemann seiner Tochter Fatima.", 1366),
 ("كَانَ مِنَ السَّابِقِينَ الْأَوَّلِينَ، وَشَهِدَ بَدْرًا وَمَا بَعْدَهَا.", "Er gehörte zu den Ersten im Islam und nahm an Badr und allen späteren Schlachten teil.", 1366),
 ("أَسْلَمَ وَهُوَ صَبِيٌّ، وَاخْتُلِفَ فِي عُمُرِهِ يَوْمَئِذٍ.", "Er nahm den Islam als Junge an; über sein damaliges Alter gibt es verschiedene Angaben.", 1367),
 ("وَجَدَهُ النَّبِيُّ ﷺ نَائِمًا فِي الْمَسْجِدِ وَعَلَيْهِ التُّرَابُ، فَقَالَ: قُمْ أَبَا تُرَابٍ.", "Der Prophet ﷺ fand ihn schlafend in der Moschee, mit Staub bedeckt, und sagte: Steh auf, Abu Turab (Vater des Staubes)!", 1366),
 ("وَكَانَ هَذَا الِاسْمُ أَحَبَّ أَسْمَائِهِ إِلَيْهِ.", "Dieser Name war ihm der liebste.", 1366),
 ("وَيَوْمَ خَيْبَرَ أَعْطَاهُ النَّبِيُّ ﷺ الرَّايَةَ، فَفَتَحَ اللَّهُ عَلَى يَدَيْهِ.", "Am Tag von Khaybar gab ihm der Prophet ﷺ die Fahne, und Allah schenkte den Sieg durch ihn.", 1370),
 ("وَقَالَ لَهُ النَّبِيُّ ﷺ: أَنْتَ مِنِّي بِمَنْزِلَةِ هَارُونَ مِنْ مُوسَى، إِلَّا أَنَّهُ لَا نَبِيَّ بَعْدِي.", "Der Prophet ﷺ sagte zu ihm: Du stehst zu mir wie Harun zu Musa, nur dass es nach mir keinen Propheten gibt.", 1370),
 ("وَقَالَ النَّبِيُّ ﷺ: مَنْ كُنْتُ مَوْلَاهُ فَعَلِيٌّ مَوْلَاهُ.", "Und der Prophet ﷺ sagte: Wessen Schutzfreund ich bin, dessen Schutzfreund ist ʿAli.", 1371),
], [
 ("hadith", "قم أبا تراب قم أبا تراب", "Steh auf, Abu Turab, steh auf, Abu Turab!", 1366, "أخرجه مسلم (laut adh-Dhahabi)"),
 ("athar", "ما كان لعلي اسم أحب إليه منه، إن كان ليفرح إذا دعي به", "Kein Name war ʿAli lieber als dieser; er freute sich, wenn man ihn so rief. (Sahl ibn Saʿd)", 1366),
 ("hadith", "من كنت مولاه فعلي مولاه", "Wessen Schutzfreund ich bin, dessen Schutzfreund ist ʿAli.", 1371, "هذا حديث صحيح (adh-Dhahabi)"),
])
